/**
 * Memastikan tabel Master_Pegawai_POA, Master_Standar_Pelatihan, dan TX_TU_Pelatihan_Pegawai terisi data awal.
 * Idempoten: Hanya menyemaikan jika sheet masih kosong (atau force === true).
 *
 * @param {boolean} [force=false]
 * @returns {{success:boolean, pegawaiCount:number, standarCount:number}}
 */
function ensurePegawaiPelatihanSeeded(force) {
  var tuId = ensureTuSpreadsheet();
  var ss = SpreadsheetApp.openById(tuId);

  var pSheet = ss.getSheetByName(SHEET_TU.PEGAWAI_MASTER) || _autoCreateTuSheet(ss, SHEET_TU.PEGAWAI_MASTER);
  var sSheet = ss.getSheetByName(SHEET_TU.STANDAR_PELATIHAN) || _autoCreateTuSheet(ss, SHEET_TU.STANDAR_PELATIHAN);
  var tSheet = ss.getSheetByName(SHEET_TU.PELATIHAN_PEGAWAI) || _autoCreateTuSheet(ss, SHEET_TU.PELATIHAN_PEGAWAI);

  var pLast = pSheet.getLastRow();
  var sLast = sSheet.getLastRow();

  var seededPegawai = 0;
  var seededStandar = 0;

  // 1. Seed Master Standar Pelatihan (38 kelompok jabatan)
  if (sLast <= 1 || force) {
    if (force && sLast > 1) {
      sSheet.getRange(2, 1, sLast - 1, sSheet.getLastColumn()).clearContent();
    }
    var sRows = [];
    for (var grp in STANDAR_PELATIHAN_RESMI) {
      if (STANDAR_PELATIHAN_RESMI.hasOwnProperty(grp)) {
        var items = STANDAR_PELATIHAN_RESMI[grp];
        for (var i = 0; i < items.length; i++) {
          var itm = items[i];
          sRows.push([
            itm.kode,
            grp,
            itm.tingkat || 'ALL',
            itm.kat || 'TEKNIS',
            itm.nama,
            itm.wajib ? true : false,
            i + 1
          ]);
        }
      }
    }
    if (sRows.length > 0) {
      sSheet.getRange(2, 1, sRows.length, sRows[0].length).setValues(sRows);
      seededStandar = sRows.length;
    }
  }

  // 2. Seed Master Pegawai POA & Awak Kapal (504 Personel)
  if (pLast <= 1 || force) {
    if (force && pLast > 1) {
      pSheet.getRange(2, 1, pLast - 1, pSheet.getLastColumn()).clearContent();
    }
    var nowStr = new Date().toISOString();
    var pRows = [];
    for (var p = 0; p < SEED_PEGAWAI_POA_AWAK.length; p++) {
      var peg = SEED_PEGAWAI_POA_AWAK[p];
      var sPeg = peg.statusKepegawaian || ((peg.unit === 'Dit. POA' || peg.lingkup === 'DIT_POA') ? 'PNS' : (peg.nip && peg.nip !== '-' ? 'PNS' : 'NON_ASN'));
      pRows.push([
        peg.pegawaiId,
        peg.nip || '-',
        peg.nama,
        peg.unit,
        peg.lingkup,
        peg.kelompokJabatan,
        peg.jabatanLengkap,
        peg.tingkatKelas,
        peg.rumpun,
        sPeg,
        peg.statusAktif || 'AKTIF',
        nowStr,
        'SYSTEM_SEED'
      ]);
    }
    if (pRows.length > 0) {
      pSheet.getRange(2, 1, pRows.length, pRows[0].length).setValues(pRows);
      seededPegawai = pRows.length;
    }
  }

  return {
    success: true,
    pegawaiCount: seededPegawai || (pSheet.getLastRow() - 1),
    standarCount: seededStandar || (sSheet.getLastRow() - 1)
  };
}
